istics Operations Handbook","source":"Knowledge","sourceKind":"knowledge","category":"document","domain":"Knowledge","description":"Carrier SLA & OTIF policy, the warehouse network, and the freight-cost / CO₂ methodology.","columnCount":0,"keyColumns":[],"fields":[{"name":"Carrier SLA & OTIF Policy.md","type":"document"},{"name":"Warehouse Network & Lanes.md","type":"document"},{"name":"Freight Cost & CO2 Methodology.md","type":"document"}]},{"id":"c-otif","name":"OTIF","table":"OTIF","source":"Knowledge","sourceKind":"concept","category":"concept","domain":"Knowledge","conceptType":"kpi","description":"On-Time-In-Full: delivered within SLA days and undamaged. Network target ≥ 95%; per-carrier floor 90%.","columnCount":0,"keyColumns":[],"fields":[]},{"id":"c-carrier","name":"Carrier","table":"Carrier","source":"Knowledge","sourceKind":"concept","category":"concept","domain":"Logistics","conceptType":"org","description":"A contracted transport provider (Meridian Freight, BlueDart Express, TransGlobal, Arctic Line), each with an SLA tier in the handbook.","columnCount":0,"keyColumns":[],"fields":[]},{"id":"c-lane","name":"Lane","table":"Lane","source":"Knowledge","sourceKind":"concept","category":"concept","domain":"Logistics","conceptType":"route","description":"Origin warehouse → destination region pairing; the unit at which SLA days and CO₂ factors are set.","columnCount":0,"keyColumns":[],"fields":[]}],"relations":[{"from":"ds-scorecard","to":"ds-shipments","label":"derived from","predicate":"derived_from","kind":"lineage","cardinality":"N:1"},{"from":"ds-shipments","to":"c-carrier","label":"performed by","predicate":"references","kind":"semantic","cardinality":"N:1"},{"from":"ds-shipments","to":"c-lane","label":"moves along","predicate":"references","kind":"semantic","cardinality":"N:1"},{"from":"kb-handbook","to":"c-otif","label":"defines","predicate":"defines","kind":"knowledge","cardinality":"1:N"},{"from":"kb-handbook","to":"c-carrier","label":"sets SLA for",