INSERT INTO public.bi_sample_dashboards (sort, name, description, widgets, layout, filters, theme)
VALUES (8, $sample$People Analytics · Sample$sample$, $sample$Headcount, attrition, engagement and pay equity across a 420-person roster — with the monthly rollup built by the bundled prep flow and an ontology tying data to the People Operations Playbook.$sample$, $sample$[{"id":"a921c40f-473c-4a55-8a92-473ca55fa921","kind":"text","title":"About this sample","text":"## 👥 People Analytics\nA **sample project** on the bundled `hr_roster` (420 employees) and `hr_dept_monthly` — the output of the **Attrition by month · Sample** prep flow. Definitions follow the **People Operations Playbook** knowledge base: attrition = exits ÷ month-end headcount, engagement is a 1–10 pulse score. Cross-filter by department or level, or open **Ask AI** to interrogate the roster in plain English. The **Business ontology** widget maps the roster, the rollup, and the playbook's concepts."},{"id":"73597101-ec77-49ab-8735-ec779ab17359","kind":"chart","title":"Headcount","source":{"kind":"local"},"sql":"SELECT COUNT(*) AS \"Active\" FROM hr_roster WHERE Status = 'Active'","chart":{"type":"kpi","valueField":"Active","label":"Active employees"},"refreshed_at":"2026-08-07T12:00:00.000Z","theme":{"card":"glass","accent":"blue"},"columns":["Active"],"rows":[{"Active":361}]},{"id":"4ec80534-38ed-42cf-84ec-38ed2cf44ec8","kind":"chart","title":"Attrition","source":{"kind":"local"},"sql":"SELECT ROUND(AVG(\"Exited Num\")*100,1) AS \"Attrition %\" FROM hr_roster","chart":{"type":"kpi","valueField":"Attrition %","label":"Exited over the window"},"refreshed_at":"2026-08-07T12:00:00.000Z","theme":{"card":"glass","accent":"rose"},"columns":["Attrition %"],"rows":[{"Attrition %":14}]},{"id":"b2d5e230-f61a-4133-8b2d-f61a1330b2d5","kind":"chart","title":"Tenure","source":{"kind":"local"},"sql":"SELECT ROUND(AVG(\"Tenure Months\")/12.0,1) AS \"Avg Tenure Years\" FROM hr_roster WHERE Status = 'Active'","chart":{"type":"kpi","valueField":"Avg Tenure Years","label":"Avg tenure (years)"},"refreshed_at":"2026-08-07T12:00:00.000Z","theme":{"card":"glass","accent":"teal"},"columns":["Avg Tenure Years"],"rows":[{"Avg Tenure Years":3}]},{"id":"855d1561-aa4d-4a11-8855-aa4da111855d","kind":"chart","title":"Engagement","source":{"kind":"local"},"sql":"SELECT ROUND(AVG(Engagement),1) AS \"Engagement\" FROM hr_roster WHERE Status = 'Active'","chart":{"type":"kpi","valueField":"Engagement","label":"Pulse score /10"},"refreshed_at":"2026-08-07T12:00:00.000Z","theme":{"card":"glass","accent":"emerald"},"columns":["Engagement"],"rows":[{"Engagement":7.6}]},{"id":"c7cd54b6-b91b-497d-8c7c-b91b97d6c7cd","kind":"chart","title":"Headcount by department","source":{"kind":"local"},"sql":"SELECT Month, Department, Headcount FROM hr_dept_monthly ORDER BY Month, Department","chart":{"type":"area","xField":"Month","yField":"Headcount","seriesField":"Department","stacked":true},"refreshed_at":"2026-08-07T12:00:00.000Z","theme":{"card":"glass","accent":"blue"},"narrative":"Prep-flow output: month-end headcount per department, stacked to the company total.","columns":["Month","Department","Headcount"],"rows":[{"Month":"2025-01","Department":"Engineering","Headcount":122},{"Month":"2025-01","Department":"Finance","Headcount":26},{"Month":"2025-01","Department":"Marketing","Headcount":32},{"Month":"2025-01","Department":"People","Headcount":23},{"Month":"2025-01","Department":"Sales","Headcount":55},{"Month":"2025-01","Department":"Support","Headcount":47},{"Month":"2025-02","Department":"Engineering","Headcount":124},{"Month":"2025-02","Department":"Finance","Headcount":27},{"Month":"2025-02","Department":"Marketing","Headcount":33},{"Month":"2025-02","Department":"People","Headcount":24},{"Month":"2025-02","Department":"Sales","Headcount":57},{"Month":"2025-02","Department":"Support","Headcount":44},{"Month":"2025-03","Department":"Engineering","Headcount":125},{"Month":"2025-03","Department":"Finance","Headcount":27},{"Month":"2025-03","Department":"Marketing","Headcount":33},{"Month":"2025-03","Depar