-- ── Per-user extras: semantic models + prep flows ────────────────────────────
-- Both tables are strictly per-user (user_id NOT NULL), so these seed like the
-- sample dashboards do: a SECURITY DEFINER function, called on signup and
-- backfilled below. table_id / output_table_id resolve lazily by name — NULL
-- until the global sample datasets exist, which is fine: the semantic layer
-- compiles from source_table (the name), and the prep flow resolves its output
-- when run.
CREATE OR REPLACE FUNCTION public.seed_bi_sample_extras(_uid uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _ship_tid uuid;
  _roster_tid uuid;
BEGIN
  SELECT id INTO _ship_tid FROM public.user_data_tables
    WHERE name = 'supply_shipments' AND is_sample = true AND user_id IS NULL LIMIT 1;
  SELECT id INTO _roster_tid FROM public.user_data_tables
    WHERE name = 'hr_roster' AND is_sample = true AND user_id IS NULL LIMIT 1;

  INSERT INTO public.semantic_models
    (user_id, name, label, description, source_kind, table_id, source_table, dimensions, metrics)
  SELECT _uid, 'supply_shipments_model', 'Supply Shipments',
         'Governed logistics metrics over supply_shipments — OTIF, transit, freight and CO₂, sliced by carrier, mode, lane and month.',
         'data_table', _ship_tid, 'supply_shipments',
         $sample$[{"name":"carrier","sql":"\"Carrier\"","type":"categorical"},{"name":"mode","sql":"\"Mode\"","type":"categorical"},{"name":"origin_warehouse","sql":"\"Origin Warehouse\"","type":"categorical"},{"name":"dest_region","sql":"\"Dest Region\"","type":"categorical"},{"name":"category","sql":"\"Category\"","type":"categorical"},{"name":"order_date","sql":"\"Order Date\"","type":"time"}]$sample$::jsonb,
         $sample$[{"name":"shipments","agg":"count"},{"name":"units","agg":"sum","sql":"\"Units\""},{"name":"freight_cost","agg":"sum","sql":"\"Freight Cost\""},{"name":"order_value","agg":"sum","sql":"\"Order Value\""},{"name":"otif_pct","agg":"avg","sql":"\"On Time Num\""},{"name":"avg_transit_days","agg":"avg","sql":"\"Transit Days\""},{"name":"co2_kg","agg":"sum","sql":"\"CO2 Kg\""}]$sample$::jsonb
  WHERE NOT EXISTS (
    SELECT 1 FROM public.semantic_models m WHERE m.user_id = _uid AND m.name = 'supply_shipments_model'
  );

  INSERT INTO public.semantic_models
    (user_id, name, label, description, source_kind, table_id, source_table, dimensions, metrics)
  SELECT _uid, 'hr_roster_model', 'Employee Roster',
         'Governed people metrics over hr_roster — headcount, attrition, tenure, pay and engagement by department, level and location.',
         'data_table', _roster_tid, 'hr_roster',
         $sample$[{"name":"department","sql":"\"Department\"","type":"categorical"},{"name":"level","sql":"\"Level\"","type":"categorical"},{"name":"location","sql":"\"Location\"","type":"categorical"},{"name":"gender","sql":"\"Gender\"","type":"categorical"},{"name":"work_mode","sql":"\"Work Mode\"","type":"categorical"},{"name":"hire_date","sql":"\"Hire Date\"","type":"time"}]$sample$::jsonb,
         $sample$[{"name":"headcount","agg":"count"},{"name":"exits","agg":"sum","sql":"\"Exited Num\""},{"name":"avg_tenure_months","agg":"avg","sql":"\"Tenure Months\""},{"name":"avg_salary","agg":"avg","sql":"\"Salary USD\""},{"name":"avg_engagement","agg":"avg","sql":"\"Engagement\""},{"name":"avg_performance","agg":"avg","sql":"\"Performance\""}]$sample$::jsonb
  WHERE NOT EXISTS (
    SELECT 1 FROM public.semantic_models m WHERE m.user_id = _uid AND m.name = 'hr_roster_model'
  );

  INSERT INTO public.user_prep_flows (user_id, name, config, output_table_name)
  SELECT _uid, 'Carrier scorecard · Sample',
         $sample${"base":"supply_shipments","joins":[],"columns":[{"key":"supply_shipments.Month","table":"supply_shipments","column":"Month","include":true,"outputName":"Month","type":"text"},{"key":"supply_shipments.Carrier","table":"supply_shipments","column":"Carrier","include":true,"outputName":"Carrier","type":"text"},{"key":"supply_shipments.On Time Num","table":"supply_shipments","column":"On Time Num","include":true,"outputName":"On Time Num","type":"number"},{"key":"supply_shipments.Transit Days","table":"supply_shipments","column":"Transit Days","include":true,"outputName":"Transit Days","type":"number"},{"key":"supply_shipments.Freight Cost","table":"supply_shipments","column":"Freight Cost","include":true,"outputName":"Freight Cost","type":"number"},{"key":"supply_shipments.Damaged Num","table":"supply_shipments","column":"Damaged Num","include":true,"outputName":"Damaged Num","type":"number"}],"steps":[{"id":"st-agg","kind":"aggregate","groupBy":["Month","Carrier"],"measures":[{"id":"m1","column":"","fn":"count","name":"Shipments"},{"id":"m2","column":"On Time Num","fn":"avg","name":"On Time Pct"},{"id":"m3","column":"Transit Days","fn":"avg","name":"Avg Transit Days"},{"id":"m4","column":"Freight Cost","fn":"sum","name":"Freight Cost"},{"id":"m5","column":"Damaged Num","fn":"avg","name":"Damage Pct"}]}]}$sample$::jsonb,
         'supply_carrier_scorecard_run'
  WHERE NOT EXISTS (
    SELECT 1 FROM public.user_prep_flows f WHERE f.user_id = _uid AND f.name = 'Carrier scorecard · Sample'
  );

  INSERT INTO public.user_prep_flows (user_id, name, config, output_table_name)
  SELECT _uid, 'Attrition by month · Sample',
         $sample${"base":"hr_roster","joins":[],"columns":[{"key":"hr_roster.Exit Month","table":"hr_roster","column":"Exit Month","include":true,"outputName":"Exit Month","type":"text"},{"key":"hr_roster.Department","table":"hr_roster","column":"Department","include":true,"outputName":"Department","type":"text"},{"key":"hr_roster.Tenure Months","table":"hr_roster","column":"Tenure Months","include":true,"outputName":"Tenure Months","type":"number"},{"key":"hr_roster.Status","table":"hr_roster","column":"Status","include":true,"outputName":"Status","type":"text"}],"steps":[{"id":"st-f","kind":"filter","combine":"AND","conditions":[{"id":"c1","column":"Status","op":"=","value":"Exited"}]},{"id":"st-agg","kind":"aggregate","groupBy":["Exit Month","Department"],"measures":[{"id":"m1","column":"","fn":"count","name":"Exits"},{"id":"m2","column":"Tenure Months","fn":"avg","name":"Avg Tenure At Exit"}]}]}$sample$::jsonb,
         'hr_exits_by_month'
  WHERE NOT EXISTS (
    SELECT 1 FROM public.user_prep_flows f WHERE f.user_id = _uid AND f.name = 'Attrition by month · Sample'
  );
END;
$$;

-- Signup trigger now seeds dashboards AND the extras.
CREATE OR REPLACE FUNCTION public.handle_new_user_bi_samples()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  PERFORM public.seed_bi_sample_dashboards(NEW.id);
  PERFORM public.seed_bi_sample_extras(NEW.id);
  RETURN NEW;
END;
$$;

-- Backfill: existing accounts get the new dashboards, models and flows.
DO $$
DECLARE u record;
BEGIN
  FOR u IN SELECT id FROM auth.users LOOP
    PERFORM public.seed_bi_sample_dashboards(u.id);
    PERFORM public.seed_bi_sample_extras(u.id);
  END LOOP;
END $$;
